import unittest
from candidate import pluck

class TestPluckFunction(unittest.TestCase):
    def test_pluck_normal_case_with_smallest_even(self):
        self.assertEqual(pluck([4, 2, 3]), [2, 1])

    def test_pluck_normal_case_with_multiple_smallest_evens(self):
        self.assertEqual(pluck([1, 2, 3, 2, 4]), [2, 1])

    def test_pluck_normal_case_with_zero_as_smallest_even(self):
        self.assertEqual(pluck([5, 0, 3, 0, 4, 2]), [0, 1])

    def test_pluck_empty_array(self):
        self.assertEqual(pluck([]), [])

    def test_pluck_array_with_no_evens(self):
        self.assertEqual(pluck([1, 3, 5]), [])

    def test_pluck_single_element_even(self):
        self.assertEqual(pluck([2]), [2, 0])

    def test_pluck_single_element_odd(self):
        self.assertEqual(pluck([1]), [])

    def test_pluck_all_evens_same_value(self):
        self.assertEqual(pluck([2, 4, 6]), [2, 0])

    def test_pluck_all_evens_different_values(self):
        self.assertEqual(pluck([6, 2, 4]), [2, 1])

    def test_pluck_large_array(self):
        self.assertEqual(pluck([10000, 20000, 3000, 4000, 5000]), [3000, 2])

    def test_pluck_negative_values_allowed(self):
        self.assertEqual(pluck([-2, -4, 1, 3]), [-4, 1])

    def test_pluck_duplicate_min_even(self):
        self.assertEqual(pluck([2, 2, 4, 6]), [2, 0])

    def test_pluck_first_even_at_end(self):
        self.assertEqual(pluck([1, 3, 5, 2]), [2, 3])

    def test_pluck_first_even_at_start(self):
        self.assertEqual(pluck([2, 1, 3]), [2, 0])
